// ============================================================
// SERVER — chat.gateway.ts
// ============================================================
import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';

interface TypingPayload {
  roomId: string;
  userId: string;
}

@WebSocketGateway({ cors: true })
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  // No throttle, no debounce, no per-connection rate limit here.
  // Every inbound `typing` event triggers exactly one outbound emit
  // per receiver, so cost = keystrokes x (roomSize - 1) receivers x concurrent typists.
  // Note: this handler never touches a DB/cache — typing state is
  // intentionally unpersisted, which is a property worth keeping.
  @SubscribeMessage('typing')
  handleTyping(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: TypingPayload,
  ): void {
    client.to(payload.roomId).emit('typing', { userId: payload.userId });
  }
}

